      "data": "/* ========= 气测录井异常智能识别示范样式 ========= */\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;\n  background: #fbfaf6;\n  color: #242b2e;\n  font-size: 12px;\n  padding: 10px 12px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n.panel { max-width: none; margin: 0; }\n.layout { display: grid; grid-template-columns: minmax(0,1fr) 232px; gap: 10px; align-items: start; }\n.side { position: sticky; top: 6px; }\n\n.head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 6px; }\nh1 { font-size: 15px; font-weight: 600; margin: 0 0 3px; }\n.lead { font-size: 11.5px; color: #5d666d; margin: 0; }\n.badge {\n  flex-shrink: 0; font-size: 10px; color: #235f51; background: #e9f1ec;\n  border: 1px solid #d3e2d8; border-radius: 20px; padding: 2px 8px; white-space: nowrap;\n}\n\n.data-src { font-size: 10.5px; color: #9ba3a9; margin: 0 0 8px; padding: 0 2px; line-height: 1.5; }\n.data-src b { color: #6d767d; font-weight: 600; }\n\n.section { background: #fff; border: 1px solid #e9e4d8; border-radius: 9px; padding: 8px 10px; margin-bottom: 8px; }\n.sec-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 6px; }\nh2 { font-size: 12.5px; font-weight: 600; color: #235f51; margin: 0; }\nh3 {\n  font-size: 10px; color: #8a9298; letter-spacing: .08em; margin: 0 0 4px;\n  text-transform: uppercase; font-weight: 600;\n}\n.hint { font-size: 10.5px; color: #8a9298; margin: 0; }\n\n/* ---------- 页签 ---------- */\n.tabs { display: flex; gap: 4px; margin: 0 0 8px; border-bottom: 1px solid #e6e0d2; }\n.tab {\n  font-family: inherit; font-size: 11.5px; color: #5d666d; background: #f5f2ea;\n  border: 1px solid #e6e0d2; border-radius: 7px 7px 0 0; padding: 6px 14px;\n  cursor: pointer; border-bottom: none;\n}\n.tab:hover { background: #efeade; }\n.tab.active { color: #235f51; background: #fff; border-color: #cfdfd6; font-weight: 600; }\n.tabpane { display: none; }\n.tabpane.active { display: block; }\n\n/* ---------- 控制 ---------- */\n.controls { display: grid; grid-template-columns: 1fr; gap: 6px; }\n.ctl {\n  background: #f5f2ea; border-radius: 7px; padding: 6px 8px;\n  display: flex; flex-direction: column; gap: 2px; min-width: 0;\n}\n.ctl label { font-size: 11px; font-weight: 500; display: flex; justify-content: space-between; align-items: baseline; gap: 6px; white-space: nowrap; }\n.ctl output { font-family: 'Consolas', 'Courier New', monospace; color: #235f51; font-weight: 600; font-size: 11px; flex-shrink: 0; }\n.ctl input[type=\"range\"] { width: 100%; height: 16px; margin: 0; accent-color: #2f7d6b; }\n.ctl select {\n  font-family: inherit; font-size: 11px; color: #235f51; font-weight: 600;\n  background: #fff; border: 1px solid #d8d2c2; border-radius: 5px; padding: 3px 4px;\n  width: 100%; cursor: pointer;\n}\n.ctl .tip { font-size: 10px; color: #9ba3a9; line-height: 1.3; }\n\n.btnrow { display: flex; align-items: center; gap: 8px; margin-top: 8px; flex-wrap: wrap; }\nbutton {\n  font-family: inherit; font-size: 10.5px; color: #235f51; background: #f2f6f3;\n  border: 1px solid #cfdfd6; border-radius: 6px; padding: 4px 10px; cursor: pointer;\n}\nbutton:hover { background: #e6f0ea; }\n.btn-note { font-size: 10px; color: #9ba3a9; }\n\n/* ---------- 图表 ---------- */\n.chart-box { position: relative; background: #fdfcf9; border-radius: 8px; padding: 4px; }\n.chart-box canvas { display: block; max-width: 720px; width: 100%; height: auto; margin: 0 auto; border-radius: 6px; cursor: crosshair; }\n.chart-wrap { background: #fdfcf9; border-radius: 8px; padding: 4px; position: relative; }\n.chart-wrap svg { display: block; max-width: 100%; width: 100%; height: auto; margin: 0 auto; }\n\n.grid-charts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n.chart { min-width: 0; }\n.chart svg { display: block; max-width: 100%; width: 100%; height: auto; background: #fdfcf9; border-radius: 8px; }\n.legend { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 4px; font-size: 10px; color: #5d666d; }\n.legend i { display: inline-block; width: 10px; height: 2px; vertical-align: middle; margin-right: 3px; border-radius: 1px; }\n.legend i.dot { width: 7px; height: 7px; border-radius: 50%; }\n\n.chart-tip {\n  position: absolute; z-index: 6; display: none; pointer-events: none;\n  max-width: 260px; padding: 5px 8px; border-radius: 6px;\n  background: #fff; border: 1px solid #ded8c8; color: #3d464b;\n  box-shadow: 0 2px 10px rgba(30, 40, 35, 0.14);\n  font-size: 10.5px; line-height: 1.55;\n}\n.chart-tip b { color: #235f51; font-family: ui-monospace, Consolas, monospace; }\n\n/* ---------- 指标卡 ---------- */\n.metrics { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }\n.mcard { background: #f5f2ea; border-radius: 8px; padding: 6px 8px; min-width: 0; }\n.mcard span { display: block; font-size: 10px; color: #79828a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.mcard b { font-family: 'Consolas', 'Courier New', monospace; font-size: 15px; color: #235f51; font-weight: 600; line-height: 1.25; }\n.mcard b small { font-size: 10px; color: #8a9298; font-weight: 400; }\n.mcard.warn b { color: #c9a15a; }\n.mcard.bad b { color: #b05a51; }\n\n.verdict { margin-top: 6px; padding: 6px 10px; border-radius: 6px; font-size: 11px; line-height: 1.5; }\n.verdict.ok { background: #e9f3ec; color: #35765a; }\n.verdict.warn { background: #faf3e2; color: #9a7a1c; }\n.verdict.bad { background: #faeae6; color: #a85147; }\n.verdict b { font-family: 'Consolas', 'Courier New', monospace; }\n\n.foot { font-size: 10px; color: #9ba3a9; line-height: 1.5; padding: 0 4px 2px; margin: 4px 0 0; }\n\n/* ---------- 数据来源页 ---------- */\n.src-bar {\n  display: flex; justify-content: space-between; align-items: flex-start; gap: 10px;\n  background: #f1f7f4; border: 1px solid #d3e2d8; border-radius: 7px;\n  padding: 6px 10px; margin-bottom: 8px; font-size: 10.5px; color: #4d565b; line-height: 1.55;\n}\n.src-bar b { color: #235f51; }\n.src-bar a { flex-shrink: 0; color: #2f7d6b; text-decoration: none; font-weight: 600; }\n.src-bar a:hover { text-decoration: underline; }\n.tag.real { font-size: 9.5px; border-radius: 3px; padding: 1px 6px; white-space: nowrap; font-weight: 600; color: #235f51; background: #e9f1ec; border: 1px solid #cfe3d7; }\n.r-detail {\n  margin-top: 8px; padding: 7px 10px; min-height: 34px;\n  border-left: 3px solid #cfdfd6; border-radius: 0 5px 5px 0;\n  background: #faf9f4; font-size: 10.5px; line-height: 1.6; color: #5d666d;\n}\n.r-detail.active { border-left-color: #b05a51; background: #fbf5f1; }\n.r-detail b { color: #242b2e; }\n\n.lit-table { width: 100%; border-collapse: collapse; font-size: 10.5px; margin-top: 4px; }\n.lit-table th, .lit-table td { padding: 4px 6px; border-bottom: 1px solid #ece5d6; text-align: left; vertical-align: top; }\n.lit-table th { color: #79828a; font-weight: 500; background: #faf8f2; }\n.lit-table td.num { font-family: ui-monospace, Consolas, monospace; }\n.lit-table a { color: #2f7d6b; text-decoration: none; }\n.lit-table a:hover { text-decoration: underline; }\n#src-body tr { cursor: default; }\n#src-body tr:hover { background: #f5f2ea; }\n\n@media (max-width: 720px) {\n  .grid-charts { grid-template-columns: 1fr; }\n  .layout { grid-template-columns: 1fr; }\n  .side { position: static; }\n}\n@media (max-width: 520px) {\n  .metrics { grid-template-columns: repeat(2, 1fr); }\n}\n"
